// mcp-server/src/tools/directExec.ts
function registerDirectExecTools(server2) {
  server2.tool(
    "execute_cross_perp",
    "Execute a cross-margin perpetual trade directly with a private key (no managed custody). Supports TP/SL and builder fees.",
    {
      privateKey: external_exports.string().describe("Wallet private key (hex)"),
      coin: external_exports.string().describe("Asset symbol, e.g. 'BTC'"),
      isLong: external_exports.boolean().describe("True for long, false for short"),
      price: external_exports.string().describe("Price in USD"),
      positionSize: external_exports.string().describe("Position size"),
      reduceOnly: external_exports.boolean().optional().default(false),
      leverage: external_exports.number().optional().describe("Leverage for cross-margin (calls updateLeverage before placing)"),
      isMarket: external_exports.boolean().optional().default(true).describe("True for market, false for limit"),
      takeProfitPrice: external_exports.string().optional().describe("Take-profit price"),
      takeProfitTrigger: external_exports.string().optional().describe("Take-profit trigger price"),
      stopLossPrice: external_exports.string().optional().describe("Stop-loss price"),
      stopLossTrigger: external_exports.string().optional().describe("Stop-loss trigger price"),
      builderFeeAddress: external_exports.string().optional().describe("Builder fee wallet address"),
      builderFeeRate: external_exports.number().optional().describe("Builder fee rate in basis points")
    },
    async (params) => handleToolCall(async () => {
      const sdk = getSdk();
      const tradeParams = {
        coin: params.coin,
        isLong: params.isLong,
        price: params.price,
        positionSize: params.positionSize,
        reduceOnly: params.reduceOnly,
        leverage: params.leverage
      };
      if (params.takeProfitPrice && params.takeProfitTrigger) {
        tradeParams.takeProfit = { price: params.takeProfitPrice, triggerPrice: params.takeProfitTrigger };
      }
      if (params.stopLossPrice && params.stopLossTrigger) {
        tradeParams.stopLoss = { price: params.stopLossPrice, triggerPrice: params.stopLossTrigger };
      }
      if (params.builderFeeAddress && params.builderFeeRate) {
        tradeParams.builderFee = { address: params.builderFeeAddress, feeRate: params.builderFeeRate };
      }
      return sdk.hlExecuteCrossPerp(params.privateKey, tradeParams, params.isMarket);
    })
  );
  server2.tool(
    "execute_isolated_perp",
    "Execute an isolated-margin perpetual trade directly with a private key. Requires explicit leverage.",
    {
      privateKey: external_exports.string().describe("Wallet private key (hex)"),
      coin: external_exports.string().describe("Asset symbol"),
      isLong: external_exports.boolean().describe("True for long, false for short"),
      price: external_exports.string().describe("Price in USD"),
      positionSize: external_exports.string().describe("Position size"),
      leverage: external_exports.number().describe("Leverage (required for isolated margin)"),
      reduceOnly: external_exports.boolean().optional().default(false),
      isMarket: external_exports.boolean().optional().default(true),
      takeProfitPrice: external_exports.string().optional(),
      takeProfitTrigger: external_exports.string().optional(),
      stopLossPrice: external_exports.string().optional(),
      stopLossTrigger: external_exports.string().optional(),
      builderFeeAddress: external_exports.string().optional(),
      builderFeeRate: external_exports.number().optional()
    },
    async (params) => handleToolCall(async () => {
      const sdk = getSdk();
      const tradeParams = {
        coin: params.coin,
        isLong: params.isLong,
        price: params.price,
        positionSize: params.positionSize,
        leverage: params.leverage,
        reduceOnly: params.reduceOnly
      };
      if (params.takeProfitPrice && params.takeProfitTrigger) {
        tradeParams.takeProfit = { price: params.takeProfitPrice, triggerPrice: params.takeProfitTrigger };
      }
      if (params.stopLossPrice && params.stopLossTrigger) {
        tradeParams.stopLoss = { price: params.stopLossPrice, triggerPrice: params.stopLossTrigger };
      }
      if (params.builderFeeAddress && params.builderFeeRate) {
        tradeParams.builderFee = { address: params.builderFeeAddress, feeRate: params.builderFeeRate };
      }
      return sdk.hlExecuteIsolatedPerp(params.privateKey, tradeParams, params.isMarket);
    })
  );
  server2.tool(
    "execute_spot",
    "Execute a spot trade directly on HyperLiquid with a private key.",
    {
      privateKey: external_exports.string().describe("Wallet private key (hex)"),
      coin: external_exports.string().describe("Asset symbol"),
      isBuy: external_exports.boolean().describe("True for buy, false for sell"),
      price: external_exports.string().describe("Price"),
      size: external_exports.string().describe("Trade size"),
      isMarket: external_exports.boolean().optional().default(true),
      builderFeeAddress: external_exports.string().optional(),
      builderFeeRate: external_exports.number().optional()
    },
    async (params) => handleToolCall(async () => {
      const sdk = getSdk();
      const spotParams = {
        coin: params.coin,
        isBuy: params.isBuy,
        price: params.price,
        size: params.size
      };
      if (params.builderFeeAddress && params.builderFeeRate) {
        spotParams.builderFee = { address: params.builderFeeAddress, feeRate: params.builderFeeRate };
      }
      return sdk.hlExecuteSpot(params.privateKey, spotParams, params.isMarket);
    })
  );
  server2.tool(
    "direct_cancel_order",
    "Cancel an open order directly with a private key on HyperLiquid.",
    {
      privateKey: external_exports.string().describe("Wallet private key (hex)"),
      coin: external_exports.string().describe("Asset symbol"),
      orderId: external_exports.number().describe("Order ID (numeric)")
    },
    async ({ privateKey, coin, orderId }) => handleToolCall(async () => {
      const sdk = getSdk();
      return sdk.hlDirectCancelOrder(privateKey, coin, orderId);
    })
  );
}

